(955,1719,$mw$E1806C6F89337EBDA7635273599A46857802FAE4640DC1214E0F40691C108187$mw$,$mw$20ef3ca7b5b0c27e610e5ea4a76a05af$mw$,$mw$$mw$,$mw${"Id":1719,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"حل المعادلة $\\log_2(x-1)=4$ مع التحقق من مجال اللوغاريتم.","TitleEn":"Solve $\\log_2(x-1)=4$ and check the logarithm's domain.","QuestionTextAr":"حل المعادلة $\\log_2(x-1)=4$ مع التحقق من مجال اللوغاريتم.","QuestionTextEn":"Solve $\\log_2(x-1)=4$ and check the logarithm's domain.","DetailedSolutionAr":"القانون المستخدم: $\\log_b A=c$ تكافئ $A=b^c$ بشرط $A>0$. بالتالي $x-1=2^4=16$، ومنه $x=17$. شرط المجال $x-1>0$ أي $x>1$؛ والحل $17$ يحققه. التحقق: $\\log_2(17-1)=\\log_2 16=4$.","DetailedSolutionEn":"Rule used: log_b(A)=c iff A=b^c, provided A>0. Thus x−1=2^4=16 and x=17. The domain condition is x−1>0, or x>1; 17 satisfies it. Check: log_2(17−1)=log_2(16)=4.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6865,"Order":1,"LatexCode":"15","IsCorrect":false},{"Id":6866,"Order":2,"LatexCode":"17","IsCorrect":true},{"Id":6867,"Order":3,"LatexCode":"16","IsCorrect":false},{"Id":6868,"Order":4,"LatexCode":"5","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"اكتب شرط إيجابية المدخل.","En":"State the positive-argument condition."},{"Ar":"حوّل المعادلة إلى أسية ثم حل وتحقق من المجال.","En":"Convert to exponential form, solve, and check the domain."}],"Title":{"Ar":"حل المعادلة $\\log_2(x-1)=4$ مع التحقق من مجال اللوغاريتم.","En":"Solve $\\log_2(x-1)=4$ and check the logarithm's domain."},"Points":10,"Options":[{"Reason":{"Ar":"15 يجعل المدخل 14 لا 16.","En":"15 makes the argument 14, not 16."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"15"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"17"},{"Reason":{"Ar":"16 هو المدخل المطلوب وليس قيمة المتغير.","En":"16 is the required argument, not the variable."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"16"},{"Reason":{"Ar":"5 يجعل المدخل 4 ولوغاريتمه 2.","En":"5 makes the argument 4, whose logarithm is 2."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"5"}],"StageId":3,"Question":{"Ar":"حل المعادلة $\\log_2(x-1)=4$ مع التحقق من مجال اللوغاريتم.","En":"Solve $\\log_2(x-1)=4$ and check the logarithm's domain."},"Solution":{"Idea":{"Ar":"نحوّل المعادلة اللوغاريتمية إلى أسية مع مراعاة مجال المدخل.","En":"Convert the logarithmic equation into an exponential equation while respecting the input domain."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"$x-1>0\\Rightarrow x>1$","En":"$x-1>0\\Rightarrow x>1$"},{"Ar":"$x-1=2^4=16$","En":"$x-1=2^4=16$"},{"Ar":"نضيف 1 إلى الطرفين فنحصل على 17، وهو ضمن المجال.","En":"Add 1 to both sides to obtain 17, which lies in the domain."}],"Result":{"Ar":"$17$","En":"$17$"},"CommonError":{"Ar":"لا تنس إعادة الحد المطروح إلى الطرف الآخر.","En":"Do not forget to restore the subtracted constant."},"FormulaLatex":"\\log_bu=c\\iff u=b^c,\\quad u>0","Substitution":{"Ar":"$x-1=2^4=16\\Rightarrow x=17$","En":"$x-1=2^4=16\\Rightarrow x=17$"},"Verification":{"Ar":"$17-1=16>0,\\quad\\log_2 16=4$","En":"$17-1=16>0,\\quad\\log_2 16=4$"}},"TrackIds":[11],"CategoryId":86,"PrimarySkillId":313,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"اكتب شرط إيجابية المدخل.","En":"State the positive-argument condition."},{"Ar":"حوّل المعادلة إلى أسية ثم حل وتحقق من المجال.","En":"Convert to exponential form, solve, and check the domain."}],"Solution":{"Idea":{"Ar":"نحوّل المعادلة اللوغاريتمية إلى أسية مع مراعاة مجال المدخل.","En":"Convert the logarithmic equation into an exponential equation while respecting the input domain."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"$x-1>0\\Rightarrow x>1$","En":"$x-1>0\\Rightarrow x>1$"},{"Ar":"$x-1=2^4=16$","En":"$x-1=2^4=16$"},{"Ar":"نضيف 1 إلى الطرفين فنحصل على 17، وهو ضمن المجال.","En":"Add 1 to both sides to obtain 17, which lies in the domain."}],"Result":{"Ar":"$17$","En":"$17$"},"CommonError":{"Ar":"لا تنس إعادة الحد المطروح إلى الطرف الآخر.","En":"Do not forget to restore the subtracted constant."},"FormulaLatex":"\\log_bu=c\\iff u=b^c,\\quad u>0","Substitution":{"Ar":"$x-1=2^4=16\\Rightarrow x=17$","En":"$x-1=2^4=16\\Rightarrow x=17$"},"Verification":{"Ar":"$17-1=16>0,\\quad\\log_2 16=4$","En":"$17-1=16>0,\\quad\\log_2 16=4$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"15 يجعل المدخل 14 لا 16.","En":"15 makes the argument 14, not 16."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"16 هو المدخل المطلوب وليس قيمة المتغير.","En":"16 is the required argument, not the variable."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"5 يجعل المدخل 4 ولوغاريتمه 2.","En":"5 makes the argument 4, whose logarithm is 2."},"Order":4}]}$mw$,$mw$نحوّل المعادلة اللوغاريتمية إلى أسية مع مراعاة مجال المدخل.

$\log_bu=c\iff u=b^c,\quad u>0$

1. $x-1>0\Rightarrow x>1$

2. $x-1=2^4=16$

3. نضيف 1 إلى الطرفين فنحصل على 17، وهو ضمن المجال.

$x-1=2^4=16\Rightarrow x=17$

$17$ بلا وحدة قياس

$17-1=16>0,\quad\log_2 16=4$

لا تنس إعادة الحد المطروح إلى الطرف الآخر.$mw$,$mw$Convert the logarithmic equation into an exponential equation while respecting the input domain.

$\log_bu=c\iff u=b^c,\quad u>0$

1. $x-1>0\Rightarrow x>1$

2. $x-1=2^4=16$

3. Add 1 to both sides to obtain 17, which lies in the domain.

$x-1=2^4=16\Rightarrow x=17$

$17$ Dimensionless

$17-1=16>0,\quad\log_2 16=4$

Do not forget to restore the subtracted constant.$mw$),
(956,1720,$mw$2E77EF5FBCF8A0E6416E544B5BEB691EE32DB7500D6730B24FEAC1E464A19CC6$mw$,$mw$7e174fb7d0127c612234c79d828ba306$mw$,$mw$$mw$,$mw${"Id":1720,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"حل $\\log_3(x-2)+\\log_3 x=1$ واذكر سبب استبعاد أي جذر غير مقبول.","TitleEn":"Solve $\\log_3(x-2)+\\log_3 x=1$ and explain any excluded root.","QuestionTextAr":"حل $\\log_3(x-2)+\\log_3 x=1$ واذكر سبب استبعاد أي جذر غير مقبول.","QuestionTextEn":"Solve $\\log_3(x-2)+\\log_3 x=1$ and explain any excluded root.","DetailedSolutionAr":"القانون المستخدم: مجموع لوغاريتمين لهما الأساس نفسه هو لوغاريتم حاصل الضرب، بشرط إيجابية المدخلات. المجال $x-2>0$ و$x>0$، أي $x>2$. إذن $\\log_3[x(x-2)]=1$ فنحصل على $x(x-2)=3$ أو $(x-3)(x+1)=0$. الجذران $3$ و$-1$؛ نستبعد $-1$ لخروجه من المجال، ويبقى $x=3$.","DetailedSolutionEn":"Rule used: log_b(A)+log_b(B)=log_b(AB) only when A and B are positive. Domain x−2>0 and x>0 gives x>2. Then log_3[x(x−2)]=1 implies x(x−2)=3, so (x−3)(x+1)=0. Candidates are x=3 and x=−1; reject −1 because it violates the domain. The solution is x=3.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6869,"Order":1,"LatexCode":"-1","IsCorrect":false},{"Id":6870,"Order":2,"LatexCode":"3","IsCorrect":true},{"Id":6871,"Order":3,"LatexCode":"1","IsCorrect":false},{"Id":6872,"Order":4,"LatexCode":"5","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"اكتب شرطي إيجابية المدخلين أولاً.","En":"State positivity for both arguments first."},{"Ar":"اجمع اللوغاريتمين بخاصية الجداء، وحل المعادلة الناتجة وافحص الجذور.","En":"Combine the logarithms using the product rule, solve, and check the roots."}],"Title":{"Ar":"حل $\\log_3(x-2)+\\log_3 x=1$ واذكر سبب استبعاد أي جذر غير مقبول.","En":"Solve $\\log_3(x-2)+\\log_3 x=1$ and explain any excluded root."},"Points":10,"Options":[{"Reason":{"Ar":"−1 جذر جبري لكنه خارج مجال اللوغاريتمين.","En":"−1 is an algebraic root but violates both logarithm domains."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"-1"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"3"},{"Reason":{"Ar":"1 يجعل المدخل الأول سالباً.","En":"1 makes the first argument negative."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"1"},{"Reason":{"Ar":"5 يجعل حاصل ضرب المدخلين 15 لا 3.","En":"5 gives argument product 15, not 3."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"5"}],"StageId":3,"Question":{"Ar":"حل $\\log_3(x-2)+\\log_3 x=1$ واذكر سبب استبعاد أي جذر غير مقبول.","En":"Solve $\\log_3(x-2)+\\log_3 x=1$ and explain any excluded root."},"Solution":{"Idea":{"Ar":"يجب تحقق مجال كل لوغاريتم قبل جمعهما وحل المعادلة.","En":"Each logarithm's domain must hold before combining and solving."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"$x-2>0,\\quad x>0\\Rightarrow x>2$","En":"$x-2>0,\\quad x>0\\Rightarrow x>2$"},{"Ar":"$\\log_3[x(x-2)]=1\\Rightarrow x(x-2)=3$","En":"$\\log_3[x(x-2)]=1\\Rightarrow x(x-2)=3$"},{"Ar":"$x^2-2x-3=(x-3)(x+1)=0$","En":"$x^2-2x-3=(x-3)(x+1)=0$"},{"Ar":"نحصل على 3 و−1؛ نستبعد −1 لأنه لا يحقق المجال، ونحتفظ بـ3.","En":"The candidates are 3 and −1; reject −1 for violating the domain and retain 3."}],"Result":{"Ar":"$3$","En":"$3$"},"CommonError":{"Ar":"الجذر −1 مرفوض لأنه خارج مجال اللوغاريتمين.","En":"The root −1 is excluded because it violates the logarithm domains."},"FormulaLatex":"\\log_bu+\\log_bv=\\log_b(uv)\\quad(u,v>0)","Substitution":{"Ar":"$x>2,\\quad x(x-2)=3\\Rightarrow(x-3)(x+1)=0$","En":"$x>2,\\quad x(x-2)=3\\Rightarrow(x-3)(x+1)=0$"},"Verification":{"Ar":"$x=3>2,\\quad\\log_3 1+\\log_3 3=1$","En":"$x=3>2,\\quad\\log_3 1+\\log_3 3=1$"}},"TrackIds":[12],"CategoryId":86,"PrimarySkillId":313,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"اكتب شرطي إيجابية المدخلين أولاً.","En":"State positivity for both arguments first."},{"Ar":"اجمع اللوغاريتمين بخاصية الجداء، وحل المعادلة الناتجة وافحص الجذور.","En":"Combine the logarithms using the product rule, solve, and check the roots."}],"Solution":{"Idea":{"Ar":"يجب تحقق مجال كل لوغاريتم قبل جمعهما وحل المعادلة.","En":"Each logarithm's domain must hold before combining and solving."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"$x-2>0,\\quad x>0\\Rightarrow x>2$","En":"$x-2>0,\\quad x>0\\Rightarrow x>2$"},{"Ar":"$\\log_3[x(x-2)]=1\\Rightarrow x(x-2)=3$","En":"$\\log_3[x(x-2)]=1\\Rightarrow x(x-2)=3$"},{"Ar":"$x^2-2x-3=(x-3)(x+1)=0$","En":"$x^2-2x-3=(x-3)(x+1)=0$"},{"Ar":"نحصل على 3 و−1؛ نستبعد −1 لأنه لا يحقق المجال، ونحتفظ بـ3.","En":"The candidates are 3 and −1; reject −1 for violating the domain and retain 3."}],"Result":{"Ar":"$3$","En":"$3$"},"CommonError":{"Ar":"الجذر −1 مرفوض لأنه خارج مجال اللوغاريتمين.","En":"The root −1 is excluded because it violates the logarithm domains."},"FormulaLatex":"\\log_bu+\\log_bv=\\log_b(uv)\\quad(u,v>0)","Substitution":{"Ar":"$x>2,\\quad x(x-2)=3\\Rightarrow(x-3)(x+1)=0$","En":"$x>2,\\quad x(x-2)=3\\Rightarrow(x-3)(x+1)=0$"},"Verification":{"Ar":"$x=3>2,\\quad\\log_3 1+\\log_3 3=1$","En":"$x=3>2,\\quad\\log_3 1+\\log_3 3=1$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"−1 جذر جبري لكنه خارج مجال اللوغاريتمين.","En":"−1 is an algebraic root but violates both logarithm domains."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"1 يجعل المدخل الأول سالباً.","En":"1 makes the first argument negative."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"5 يجعل حاصل ضرب المدخلين 15 لا 3.","En":"5 gives argument product 15, not 3."},"Order":4}]}$mw$,$mw$يجب تحقق مجال كل لوغاريتم قبل جمعهما وحل المعادلة.

$\log_bu+\log_bv=\log_b(uv)\quad(u,v>0)$

1. $x-2>0,\quad x>0\Rightarrow x>2$

2. $\log_3[x(x-2)]=1\Rightarrow x(x-2)=3$

3. $x^2-2x-3=(x-3)(x+1)=0$

4. نحصل على 3 و−1؛ نستبعد −1 لأنه لا يحقق المجال، ونحتفظ بـ3.

$x>2,\quad x(x-2)=3\Rightarrow(x-3)(x+1)=0$

$3$ بلا وحدة قياس

$x=3>2,\quad\log_3 1+\log_3 3=1$

الجذر −1 مرفوض لأنه خارج مجال اللوغاريتمين.$mw$,$mw$Each logarithm's domain must hold before combining and solving.

$\log_bu+\log_bv=\log_b(uv)\quad(u,v>0)$

1. $x-2>0,\quad x>0\Rightarrow x>2$

2. $\log_3[x(x-2)]=1\Rightarrow x(x-2)=3$

3. $x^2-2x-3=(x-3)(x+1)=0$

4. The candidates are 3 and −1; reject −1 for violating the domain and retain 3.

$x>2,\quad x(x-2)=3\Rightarrow(x-3)(x+1)=0$

$3$ Dimensionless

$x=3>2,\quad\log_3 1+\log_3 3=1$

The root −1 is excluded because it violates the logarithm domains.$mw$),
(957,1721,$mw$556518271D4D0911809C635D0F71537CC55682832F493F77DE7B63EAEE0CF6D0$mw$,$mw$5634690642a39289409137e77397bb9d$mw$,$mw$$mw$,$mw${"Id":1721,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"أوجد القيمة الدقيقة $\\log_4 8$ باستخدام تغيير الأساس.","TitleEn":"Find the exact value of $\\log_4 8$ using change of base.","QuestionTextAr":"أوجد القيمة الدقيقة $\\log_4 8$ باستخدام تغيير الأساس.","QuestionTextEn":"Find the exact value of $\\log_4 8$ using change of base.","DetailedSolutionAr":"القانون المستخدم: تغيير الأساس $\\log_b a=\\log_c a/\\log_c b$ لأي أساس صالح $c$. نختار الأساس 2؛ حيث $\\log_2 8=3$ و$\\log_2 4=2$. إذن $\\log_4 8=3/2$. التحقق: $4^{3/2}=(\\sqrt4)^3=2^3=8$.","DetailedSolutionEn":"Rule used: Change of base gives log_b(a)=log_c(a)/log_c(b). Choosing c=2, log_2(8)=3 and log_2(4)=2, so log_4(8)=3/2. Verification: 4^(3/2)=(√4)^3=2³=8.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6873,"Order":1,"LatexCode":"\\frac{2}{3}","IsCorrect":false},{"Id":6874,"Order":2,"LatexCode":"\\frac{3}{2}","IsCorrect":true},{"Id":6875,"Order":3,"LatexCode":"2","IsCorrect":false},{"Id":6876,"Order":4,"LatexCode":"4","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"اختر أساساً مشتركاً يمكن التعبير عن 4 و8 بقواه.","En":"Choose a common base in whose powers both 4 and 8 can be expressed."},{"Ar":"اكتب لوغاريتم العدد على لوغاريتم الأساس بالأساس المشترك.","En":"Divide the logarithm of the argument by the logarithm of the base in the common base."}],"Title":{"Ar":"أوجد القيمة الدقيقة $\\log_4 8$ باستخدام تغيير الأساس.","En":"Find the exact value of $\\log_4 8$ using change of base."},"Points":10,"Options":[{"Reason":{"Ar":"2/3 يقلب البسط والمقام.","En":"2/3 reverses numerator and denominator."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"\\frac{2}{3}"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"\\frac{3}{2}"},{"Reason":{"Ar":"القوة الثانية للعدد 4 هي 16 لا 8.","En":"4 squared is 16, not 8."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"2"},{"Reason":{"Ar":"القوة الرابعة للعدد 4 هي 256 لا 8.","En":"4 to the fourth power is 256, not 8."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"4"}],"StageId":3,"Question":{"Ar":"أوجد القيمة الدقيقة $\\log_4 8$ باستخدام تغيير الأساس.","En":"Find the exact value of $\\log_4 8$ using change of base."},"Solution":{"Idea":{"Ar":"تغيير الأساس يسمح باستعمال أساس مشترك ملائم.","En":"Change of base allows a convenient common logarithm base."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نختار الأساس المشترك 2؛ كل الأسس موجبة ومختلفة عن 1 والمدخل موجب.","En":"Choose common base 2; all bases are positive and not 1, and the argument is positive."},{"Ar":"$8=2^3,\\quad4=2^2$","En":"$8=2^3,\\quad4=2^2$"},{"Ar":"$\\log_4 8=\\frac{\\log_2 8}{\\log_2 4}=\\frac32$","En":"$\\log_4 8=\\frac{\\log_2 8}{\\log_2 4}=\\frac32$"}],"Result":{"Ar":"$\\frac{3}{2}$","En":"$\\frac{3}{2}$"},"CommonError":{"Ar":"لا تقلب كسر تغيير الأساس.","En":"Do not invert the change-of-base fraction."},"FormulaLatex":"\\log_b a=\\frac{\\log_c a}{\\log_c b}","Substitution":{"Ar":"$\\log_4 8=\\frac{\\log_2 8}{\\log_2 4}=\\frac32$","En":"$\\log_4 8=\\frac{\\log_2 8}{\\log_2 4}=\\frac32$"},"Verification":{"Ar":"$4^{3/2}=8$","En":"$4^{3/2}=8$"}},"TrackIds":[12],"CategoryId":86,"PrimarySkillId":315,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"اختر أساساً مشتركاً يمكن التعبير عن 4 و8 بقواه.","En":"Choose a common base in whose powers both 4 and 8 can be expressed."},{"Ar":"اكتب لوغاريتم العدد على لوغاريتم الأساس بالأساس المشترك.","En":"Divide the logarithm of the argument by the logarithm of the base in the common base."}],"Solution":{"Idea":{"Ar":"تغيير الأساس يسمح باستعمال أساس مشترك ملائم.","En":"Change of base allows a convenient common logarithm base."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نختار الأساس المشترك 2؛ كل الأسس موجبة ومختلفة عن 1 والمدخل موجب.","En":"Choose common base 2; all bases are positive and not 1, and the argument is positive."},{"Ar":"$8=2^3,\\quad4=2^2$","En":"$8=2^3,\\quad4=2^2$"},{"Ar":"$\\log_4 8=\\frac{\\log_2 8}{\\log_2 4}=\\frac32$","En":"$\\log_4 8=\\frac{\\log_2 8}{\\log_2 4}=\\frac32$"}],"Result":{"Ar":"$\\frac{3}{2}$","En":"$\\frac{3}{2}$"},"CommonError":{"Ar":"لا تقلب كسر تغيير الأساس.","En":"Do not invert the change-of-base fraction."},"FormulaLatex":"\\log_b a=\\frac{\\log_c a}{\\log_c b}","Substitution":{"Ar":"$\\log_4 8=\\frac{\\log_2 8}{\\log_2 4}=\\frac32$","En":"$\\log_4 8=\\frac{\\log_2 8}{\\log_2 4}=\\frac32$"},"Verification":{"Ar":"$4^{3/2}=8$","En":"$4^{3/2}=8$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"2/3 يقلب البسط والمقام.","En":"2/3 reverses numerator and denominator."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"القوة الثانية للعدد 4 هي 16 لا 8.","En":"4 squared is 16, not 8."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"القوة الرابعة للعدد 4 هي 256 لا 8.","En":"4 to the fourth power is 256, not 8."},"Order":4}]}$mw$,$mw$تغيير الأساس يسمح باستعمال أساس مشترك ملائم.

$\log_b a=\frac{\log_c a}{\log_c b}$

1. نختار الأساس المشترك 2؛ كل الأسس موجبة ومختلفة عن 1 والمدخل موجب.

2. $8=2^3,\quad4=2^2$

3. $\log_4 8=\frac{\log_2 8}{\log_2 4}=\frac32$

$\log_4 8=\frac{\log_2 8}{\log_2 4}=\frac32$

$\frac{3}{2}$ بلا وحدة قياس

$4^{3/2}=8$

لا تقلب كسر تغيير الأساس.$mw$,$mw$Change of base allows a convenient common logarithm base.

$\log_b a=\frac{\log_c a}{\log_c b}$

1. Choose common base 2; all bases are positive and not 1, and the argument is positive.

2. $8=2^3,\quad4=2^2$

3. $\log_4 8=\frac{\log_2 8}{\log_2 4}=\frac32$

$\log_4 8=\frac{\log_2 8}{\log_2 4}=\frac32$

$\frac{3}{2}$ Dimensionless

$4^{3/2}=8$

Do not invert the change-of-base fraction.$mw$),
(958,1722,$mw$833EA212671D52F9EA321D6289C27784FDC6B6E47D309CB15E3D57DB721394F8$mw$,$mw$e10feb6c9336c765993eb4ea3aeb1e43$mw$,$mw$$mw$,$mw${"Id":1722,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"ما مجال الدالة $f(x)=\\log_2(x-5)$ على الأعداد الحقيقية؟","TitleEn":"What is the real-number domain of $f(x)=\\log_2(x-5)$?","QuestionTextAr":"ما مجال الدالة $f(x)=\\log_2(x-5)$ على الأعداد الحقيقية؟","QuestionTextEn":"What is the real-number domain of $f(x)=\\log_2(x-5)$?","DetailedSolutionAr":"القانون المستخدم: يجب أن يكون مدخل اللوغاريتم موجباً تماماً؛ $\\log_b A$ معرّف على الأعداد الحقيقية عندما $A>0$ و$b>0$ و$b\\ne1$. هنا $A=x-5$، فنحل $x-5>0$ فنحصل على $x>5$. لا تشمل مجموعة المجال العدد 5 لأن $\\log_2 0$ غير معرّف.","DetailedSolutionEn":"Rule used: A real logarithm log_b(A) requires A>0, b>0 and b≠1. For f(x)=log_2(x−5), require x−5>0, giving x>5. Equality at x=5 is excluded because log_2(0) is undefined.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6877,"Order":1,"LatexCode":"x\\ge5","IsCorrect":false},{"Id":6878,"Order":2,"LatexCode":"x>5","IsCorrect":true},{"Id":6879,"Order":3,"LatexCode":"x>0","IsCorrect":false},{"Id":6880,"Order":4,"LatexCode":"x<5","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"انتبه إلى أن المدخل هو التعبير داخل اللوغاريتم.","En":"Notice that the argument is the expression inside the logarithm."},{"Ar":"حل متباينة إيجابية التعبير داخل اللوغاريتم.","En":"Solve the inequality requiring the logarithm argument to be positive."}],"Title":{"Ar":"ما مجال الدالة $f(x)=\\log_2(x-5)$ على الأعداد الحقيقية؟","En":"What is the real-number domain of $f(x)=\\log_2(x-5)$?"},"Points":10,"Options":[{"Reason":{"Ar":"هذا الشرط يسمح بالقيمة 5 التي تجعل المدخل صفراً.","En":"This includes 5, which makes the argument zero."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"x\\ge5"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"x>5"},{"Reason":{"Ar":"x>0 يسمح بأعداد بين 0 و5 لا تحقق إيجابية المدخل.","En":"x>0 includes numbers between 0 and 5 that do not give a positive argument."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"x>0"},{"Reason":{"Ar":"x<5 يجعل المدخل سالباً.","En":"x<5 makes the argument negative."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"x<5"}],"StageId":3,"Question":{"Ar":"ما مجال الدالة $f(x)=\\log_2(x-5)$ على الأعداد الحقيقية؟","En":"What is the real-number domain of $f(x)=\\log_2(x-5)$?"},"Solution":{"Idea":{"Ar":"اللوغاريتم الحقيقي يتطلب مدخلاً موجباً تماماً.","En":"A real logarithm requires a strictly positive argument."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الأساس 2 صالح، لذا القيد الوحيد هو إيجابية المدخل.","En":"Base 2 is valid, so the only restriction is a positive argument."},{"Ar":"$x-5>0$","En":"$x-5>0$"},{"Ar":"$x>5\\iff x\\in(5,\\infty)$","En":"$x>5\\iff x\\in(5,\\infty)$"}],"Result":{"Ar":"$x>5$","En":"$x>5$"},"CommonError":{"Ar":"لا تسمح بمدخل صفري أو سالب.","En":"Do not allow a zero or negative argument."},"FormulaLatex":"\\operatorname{dom}(\\log_b u)=\\{x:u(x)>0\\}","Substitution":{"Ar":"$x-5>0\\Rightarrow x>5$","En":"$x-5>0\\Rightarrow x>5$"},"Verification":{"Ar":"$x=6\\Rightarrow x-5=1>0;\\quad x=5\\Rightarrow x-5=0$","En":"$x=6\\Rightarrow x-5=1>0;\\quad x=5\\Rightarrow x-5=0$"}},"TrackIds":[11],"CategoryId":86,"PrimarySkillId":312,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"انتبه إلى أن المدخل هو التعبير داخل اللوغاريتم.","En":"Notice that the argument is the expression inside the logarithm."},{"Ar":"حل متباينة إيجابية التعبير داخل اللوغاريتم.","En":"Solve the inequality requiring the logarithm argument to be positive."}],"Solution":{"Idea":{"Ar":"اللوغاريتم الحقيقي يتطلب مدخلاً موجباً تماماً.","En":"A real logarithm requires a strictly positive argument."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الأساس 2 صالح، لذا القيد الوحيد هو إيجابية المدخل.","En":"Base 2 is valid, so the only restriction is a positive argument."},{"Ar":"$x-5>0$","En":"$x-5>0$"},{"Ar":"$x>5\\iff x\\in(5,\\infty)$","En":"$x>5\\iff x\\in(5,\\infty)$"}],"Result":{"Ar":"$x>5$","En":"$x>5$"},"CommonError":{"Ar":"لا تسمح بمدخل صفري أو سالب.","En":"Do not allow a zero or negative argument."},"FormulaLatex":"\\operatorname{dom}(\\log_b u)=\\{x:u(x)>0\\}","Substitution":{"Ar":"$x-5>0\\Rightarrow x>5$","En":"$x-5>0\\Rightarrow x>5$"},"Verification":{"Ar":"$x=6\\Rightarrow x-5=1>0;\\quad x=5\\Rightarrow x-5=0$","En":"$x=6\\Rightarrow x-5=1>0;\\quad x=5\\Rightarrow x-5=0$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"هذا الشرط يسمح بالقيمة 5 التي تجعل المدخل صفراً.","En":"This includes 5, which makes the argument zero."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"x>0 يسمح بأعداد بين 0 و5 لا تحقق إيجابية المدخل.","En":"x>0 includes numbers between 0 and 5 that do not give a positive argument."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"x<5 يجعل المدخل سالباً.","En":"x<5 makes the argument negative."},"Order":4}]}$mw$,$mw$اللوغاريتم الحقيقي يتطلب مدخلاً موجباً تماماً.

$\operatorname{dom}(\log_b u)=\{x:u(x)>0\}$

1. الأساس 2 صالح، لذا القيد الوحيد هو إيجابية المدخل.

2. $x-5>0$

3. $x>5\iff x\in(5,\infty)$

$x-5>0\Rightarrow x>5$

$x>5$ بلا وحدة قياس

$x=6\Rightarrow x-5=1>0;\quad x=5\Rightarrow x-5=0$

لا تسمح بمدخل صفري أو سالب.$mw$,$mw$A real logarithm requires a strictly positive argument.

$\operatorname{dom}(\log_b u)=\{x:u(x)>0\}$

1. Base 2 is valid, so the only restriction is a positive argument.

2. $x-5>0$

3. $x>5\iff x\in(5,\infty)$

$x-5>0\Rightarrow x>5$

$x>5$ Dimensionless

$x=6\Rightarrow x-5=1>0;\quad x=5\Rightarrow x-5=0$

Do not allow a zero or negative argument.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" x WHERE x."Id"<>b.draft AND x."EditorialStatus" NOT IN ('Published','Withdrawn') AND (x."WizardJson"::jsonb#>>'{Question,Ar}'=p."QuestionTextAr" OR x."WizardJson"::jsonb#>>'{Question,En}'=p."QuestionTextEn")) THEN RAISE EXCEPTION 'Open draft duplicate: %',b.draft; END IF;
  IF b.wizard#>>'{Question,Ar}' IS DISTINCT FROM p."QuestionTextAr" OR b.wizard#>>'{Question,En}' IS DISTINCT FROM p."QuestionTextEn" OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  UPDATE "Problems" SET "TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
